$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'เว็บไซต์ไม่พร้อมใช้งานชั่วคราวเนื่องจากดิสก์ของเซิร์ฟเวอร์เต็ม เรากำลังแก้ไขปัญหาและจะกลับมาในเร็วๆ นี้';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'เว็บไซต์อยู่ระหว่างการบำรุงรักษาเนื่องจากดิสก์ของเซิร์ฟเวอร์ใกล้เต็ม เรากำลังแก้ไขปัญหาและจะกลับมาในเร็วๆ นี้';
