$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'สตรีมมีการขาดช่วงของไทม์สแตมป์ ซึ่งอาจทำให้เกิดการบัฟเฟอร์หรือปัญหาการเล่นบนแพลตฟอร์มปลายทาง';
